__NUXT_JSONP__("/it/about", (function(a){return {data:[{details:{slug:"it",pageTitle:"Che cos'è MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute è stata fondata nel 2002 ed è dislocata in due note aree: Westwood e Hollywood.",section1:{title:"Che cos'è MLI?",description:["Mentor Language Institute è stata fondata nel 2002 ed è dislocata in due note aree: Westwood e Hollywood.\u003Cbr \u002F\u003ELo scopo che ci siamo prefissi e’ quello di aiutare gli studenti provenienti da tutte le parti del mondo a migliorare il loro livello di conoscenza della lingua inglese."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Corsi di qualita’ a un prezzo vantaggioso",description:["Diamo valore a due cose: \u003Cb\u003E“Qualità dell'Insegnamento”\u003C\u002Fb\u003E e \u003Cb\u003E“Prezzo.”\u003Cb\u003E","L'Inglese è la lingua utilizzata a livello globale e un necessario strumento di comunicazione con persone provenienti da diverse parti del mondo. Il nostro obiettivo principale è l'acquisizione da parte degli studenti internazionali di un livello di conoscenza della lingua che garantiscano loro il successo in qualsiasi parte del globo. Per questo motivo, rivolgiamo la nostra attenzione principalmente alla qualità dell'insegnamento e alla convenienza."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"Nel 2020, più di 17000 studenti hanno scelto MLI e ottenuto il Diploma alla fine del loro percorso.",description:["I corsi da noi offerti sono ESL (programma di inglese generale costituito da 6 sezioni: Grammatica\u002FScrittura, Lettura\u002Flessico, e Comprensione orale\u002FConversazione), TOEFL e IELTS (per chi vuole successivamente trasferirsi in un college) e TOEIC.","Molti studenti hanno continuato gli studi in Università o College americani, come UCLA, USC e Santa Monica College, dopo essersi diplomati nella nostra scuola."],lists:[{link:"\u002Fit\u002Ffeature",image:a,text:"5 ragioni per scegliere MLI "},{link:"\u002Fit\u002Fcompany",image:a,text:"Informazioni sulla società"},{link:"\u002Fit\u002Fimage-gallery",image:a,text:"Galleria Foto\u002Fvideo "}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:28.447Z",updatedAt:"2025-05-26T12:06:27.572Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));